      {clusters.map(cluster => (
        <g key={cluster.id}>
          <circle cx={cluster.x} cy={cluster.y} r="5.8" />
          <text x={cluster.x + 5} y={cluster.y - 5}>{cluster.id}</text>
        </g>
      ))}
      <text x="50" y="98" textAnchor="middle">지속성 / 반응 축</text>
    </svg>
  )
}

